use vstd::prelude::*;

fn main() {}

verus!{

// File: defs.rs
pub struct Execution<T> {
    pub nat_to_state: spec_fn(nat) -> T,
}

impl<T> Execution<T> {

    pub open spec fn suffix(self, pos: nat) -> Self {
        Execution {
            nat_to_state: |i: nat| (self.nat_to_state)(i + pos),
        }
    }

}


#[verifier(reject_recursive_types(T))]
pub struct TempPred<T> {
    pub pred: spec_fn(Execution<T>) -> bool,
}

impl<T> TempPred<T> {

    pub open spec fn new(pred: spec_fn(Execution<T>) -> bool) -> Self {
        TempPred {
            pred: pred,
        }
    }

    pub open spec fn satisfied_by(self, execution: Execution<T>) -> bool {
        (self.pred)(execution)
    }

    pub open spec fn implies(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) ==> other.satisfied_by(ex))
    }

    pub open spec fn entails(self, other: Self) -> bool {
        valid(self.implies(other))
    }

}


pub open spec fn always<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| forall |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
}

pub open spec fn valid<T>(temp_pred: TempPred<T>) -> bool {
    forall |ex: Execution<T>| temp_pred.satisfied_by(ex)
}


// File: rules.rs
	#[verifier::external_body]
pub proof fn execution_equality<T>(ex1: Execution<T>, ex2: Execution<T>)
    requires forall |i: nat| #[trigger] (ex1.nat_to_state)(i) == (ex2.nat_to_state)(i),
    ensures ex1 == ex2,
	{
		unimplemented!()
	}

	#[verifier::external_body]
pub proof fn temp_pred_equality<T>(p: TempPred<T>, q: TempPred<T>)
    requires
        p.entails(q),
        q.entails(p),
    ensures p == q,
	{
		unimplemented!()
	}

// Helper lemma: suffix composes by addition.
proof fn execution_suffix_addition<T>(ex: Execution<T>, i: nat, j: nat)
    ensures ex.suffix(i).suffix(j) == ex.suffix(i + j),
{
    assert(forall |k: nat| #[trigger] (ex.suffix(i).suffix(j)).nat_to_state(k)
        == (ex.suffix(i + j)).nat_to_state(k)) by {
        reveal(Execution::suffix);
        forall |k: nat| {
            // Unfold the double suffix.
            assert(
                (ex.suffix(i).suffix(j)).nat_to_state(k)
                    == (ex.nat_to_state)((k + j) + i)
            );
            assert(
                (ex.suffix(i + j)).nat_to_state(k)
                    == (ex.nat_to_state)(k + (i + j))
            );
            assert(((k + j) + i) == (k + (i + j)));
        }
    };

    execution_equality::<T>(ex.suffix(i).suffix(j), ex.suffix(i + j));
}

proof fn always_double_equality<T>(p: TempPred<T>)
    ensures always(always(p)) == always(p),
{
    let q = always(p);
    let r = always(q);

    // r entails q
    assert(r.entails(q)) by {
        reveal(always);
        forall |ex: Execution<T>| {
            if r.satisfied_by(ex) {
                let Hr = r.satisfied_by(ex);
                // Need: q.satisfied_by(ex) i.e. forall k, p.satisfied_by(ex.suffix(k)).
                assert(q.satisfied_by(ex)) by {
                    reveal(always);
                    forall |k: nat| {
                        // From Hr, instantiate the outer forall with i = 0.
                        assert(p.satisfied_by(ex.suffix(k))) by {
                            // Hr is: forall i, q.satisfied_by(ex.suffix(i))
                            // Get q.satisfied_by(ex.suffix(0)).
                            assert(q.satisfied_by(ex.suffix(0))) by {
                                assert(Hr);
                            }
                            // Then instantiate the inner forall with j = k.
                            assert(p.satisfied_by(ex.suffix(0).suffix(k))) by {
                                reveal(always);
                                assert(q.satisfied_by(ex.suffix(0)));
                            }
                            // ex.suffix(0).suffix(k) == ex.suffix(k)
                            execution_suffix_addition::<T>(ex, 0, k);
                        }
                    }
                }
            }
        }
    };

    // q entails r
    assert(q.entails(r)) by {
        reveal(always);
        forall |ex: Execution<T>| {
            if q.satisfied_by(ex) {
                let Hq = q.satisfied_by(ex);
                assert(r.satisfied_by(ex)) by {
                    reveal(always);
                    forall |i: nat| {
                        assert(q.satisfied_by(ex.suffix(i))) by {
                            reveal(always);
                            forall |j: nat| {
                                // Need p.satisfied_by(ex.suffix(i).suffix(j))
                                assert(p.satisfied_by(ex.suffix(i).suffix(j))) by {
                                    execution_suffix_addition::<T>(ex, i, j);
                                    // Now ex.suffix(i).suffix(j) == ex.suffix(i+j),
                                    // so it follows from Hq.
                                    reveal(always);
                                    assert(p.satisfied_by(ex.suffix(i + j))) by {
                                        assert(Hq);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    };

    temp_pred_equality::<T>(r, q);
}


}

