use vstd::prelude::*;

fn main() {}

verus!{

pub struct Execution<T> {
    pub nat_to_state: spec_fn(nat) -> T,
}

impl<T> Execution<T> {
    pub open spec fn suffix(self, pos: nat) -> Self {
        Execution {
            nat_to_state: |i: nat| (self.nat_to_state)(i + pos),
        }
    }
}

#[verifier(reject_recursive_types(T))]
pub struct TempPred<T> {
    pub pred: spec_fn(Execution<T>) -> bool,
}

impl<T> TempPred<T> {
    pub open spec fn new(pred: spec_fn(Execution<T>) -> bool) -> Self {
        TempPred { pred }
    }

    pub open spec fn satisfied_by(self, execution: Execution<T>) -> bool {
        (self.pred)(execution)
    }

    pub open spec fn implies(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) ==> other.satisfied_by(ex))
    }

    pub open spec fn entails(self, other: Self) -> bool {
        valid(self.implies(other))
    }
}

pub open spec fn always<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| forall |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
}

pub open spec fn valid<T>(temp_pred: TempPred<T>) -> bool {
    forall |ex: Execution<T>| temp_pred.satisfied_by(ex)
}

// rules.rs

#[verifier::external_body]
pub proof fn execution_equality<T>(ex1: Execution<T>, ex2: Execution<T>)
    requires forall |i: nat| #[trigger] (ex1.nat_to_state)(i) == (ex2.nat_to_state)(i),
    ensures ex1 == ex2,
{
    unimplemented!()
}

#[verifier::external_body]
pub proof fn temp_pred_equality<T>(p: TempPred<T>, q: TempPred<T>)
    requires
        p.entails(q),
        q.entails(p),
    ensures p == q,
{
    unimplemented!()
}

// --- Helper lemmas about suffix ---

proof fn execution_suffix_addition<T>(ex: Execution<T>, i: nat, j: nat)
    ensures ex.suffix(i).suffix(j) == ex.suffix(i + j),
{
    execution_equality::<T>(ex.suffix(i).suffix(j), ex.suffix(i + j));
}

proof fn execution_suffix_zero_left<T>(ex: Execution<T>, j: nat)
    ensures ex.suffix(0).suffix(j) == ex.suffix(j),
{
    execution_suffix_addition::<T>(ex, 0, j);
}

// --- Main proof ---

proof fn always_double_equality<T>(p: TempPred<T>)
    ensures always(always(p)) == always(p),
{
    let q = always(p);
    let r = always(q); // always(always(p))

    // r entails q
    assert(r.entails(q)) by {
        reveal(TempPred::entails);
        reveal(valid);
        reveal(TempPred::implies);
        assert forall|ex: Execution<T>| r.satisfied_by(ex) implies q.satisfied_by(ex) by {
            if r.satisfied_by(ex) {
                // Unfold r and q definitions
                reveal(always);

                // r.satisfied_by(ex) == forall i, q.satisfied_by(ex.suffix(i))
                let Hr = r.satisfied_by(ex);

                // Need: q.satisfied_by(ex) == forall k, p.satisfied_by(ex.suffix(k))
                reveal(always);
                assert forall|k: nat| #[trigger] p.satisfied_by(ex.suffix(k)) by {
                    // From Hr, take i = 0
                    let Hq0 = Hr(0);

                    // Hq0 : q.satisfied_by(ex.suffix(0)) == forall j, p.satisfied_by(ex.suffix(0).suffix(j))
                    reveal(always);
                    let Hp = Hq0(k);

                    // ex.suffix(0).suffix(k) == ex.suffix(k)
                    execution_suffix_zero_left::<T>(ex, k);

                    // Hp is p.satisfied_by(ex.suffix(0).suffix(k)); rewrite via equality
                    assert(p.satisfied_by(ex.suffix(k)));
                    assert(Hp);
                }
            }
        }
    };

    // q entails r
    assert(q.entails(r)) by {
        reveal(TempPred::entails);
        reveal(valid);
        reveal(TempPred::implies);
        assert forall|ex: Execution<T>| q.satisfied_by(ex) implies r.satisfied_by(ex) by {
            if q.satisfied_by(ex) {
                reveal(always);

                // q.satisfied_by(ex) == forall t, p.satisfied_by(ex.suffix(t))
                let Hq = q.satisfied_by(ex);

                // Need: r.satisfied_by(ex) == forall i, q.satisfied_by(ex.suffix(i))
                reveal(always);
                assert forall|i: nat| #[trigger] q.satisfied_by(ex.suffix(i)) by {
                    // For each i, we must show q.satisfied_by(ex.suffix(i))
                    reveal(always);
                    assert forall|j: nat| #[trigger] p.satisfied_by(ex.suffix(i).suffix(j)) by {
                        let t = i + j;
                        // Hq(t) : p.satisfied_by(ex.suffix(t))
                        let Hp = Hq(t);
                        execution_suffix_addition::<T>(ex, i, j);
                        assert(p.satisfied_by(ex.suffix(i).suffix(j)));
                        assert(Hp);
                    }
                }
            }
        }
    };

    temp_pred_equality::<T>(r, q);
}

}

