proof fn execution_suffix_addition<T>(ex: Execution<T>, i: nat, j: nat)
    ensures ex.suffix(i).suffix(j) == ex.suffix(i + j),
{
    // Prove the precondition of execution_equality by unfolding suffix.
    assert forall |k: nat| #[trigger]
        (ex.suffix(i).suffix(j).nat_to_state)(k) == (ex.suffix(i + j).nat_to_state)(k)
    by {
        reveal(Execution::suffix);
        forall |k: nat| {
            assert((ex.suffix(i).suffix(j).nat_to_state)(k)
                == (ex.nat_to_state)((k + j) + i));
            assert((ex.suffix(i + j).nat_to_state)(k)
                == (ex.nat_to_state)(k + (i + j)));
            assert(((k + j) + i) == (k + (i + j)));
        }
    };

    execution_equality::<T>(ex.suffix(i).suffix(j), ex.suffix(i + j));
}

proof fn execution_suffix_left_zero<T>(ex: Execution<T>, j: nat)
    ensures ex.suffix(0).suffix(j) == ex.suffix(j),
{
    execution_suffix_addition::<T>(ex, 0, j);
}

proof fn execution_suffix_right_zero<T>(ex: Execution<T>, i: nat)
