                    reveal(always);

                    // q.satisfied_by(ex.suffix(k)) gives forall j, p.satisfied_by(ex.suffix(k).suffix(j))
                    assert(p.satisfied_by(ex.suffix(k).suffix(0))) by {
                        // Instantiate inner forall at j = 0
                    };

                    execution_suffix_right_zero::<T>(ex, k);
                };
            }
        }
    };

    // q.entails(r)
    assert(q.entails(r)) by {
        reveal(TempPred::entails);
        reveal(valid);
        reveal(TempPred::implies);
        assert forall |ex: Execution<T>| (q.satisfied_by(ex) ==> r.satisfied_by(ex)) by {
            if q.satisfied_by(ex) {
                // Unfold q.satisfied_by(ex): forall t, p.satisfied_by(ex.suffix(t))
                reveal(always);

                // Unfold r.satisfied_by(ex): need forall i, q.satisfied_by(ex.suffix(i))
                reveal(always);
                assert forall |i: nat| #[trigger] q.satisfied_by(ex.suffix(i)) by {
                    // Unfold q.satisfied_by(ex.suffix(i))
                    reveal(always);

                    // Need forall j, p.satisfied_by(ex.suffix(i).suffix(j))
                    assert forall |j: nat| #[trigger] p.satisfied_by(ex.suffix(i).suffix(j)) by {
                        let t = i + j;
                        assert(p.satisfied_by(ex.suffix(t)));
                        execution_suffix_addition::<T>(ex, i, j);
                    };
                };
            }
        }
    };

    temp_pred_equality::<T>(r, q);
}

}

