                reveal(always);
                assert forall |j: nat| #[trigger] p.satisfied_by(ex.suffix(j)) by {
                    // Take i = 0 from r.satisfied_by(ex)
                    assert(q.satisfied_by(ex.suffix(0)));
                    reveal(always);
                    // q.satisfied_by(ex.suffix(0)) = forall t, p.satisfied_by(ex.suffix(0).suffix(t))
                    assert(p.satisfied_by(ex.suffix(0).suffix(j)));
                    // Rewrite ex.suffix(0).suffix(j) to ex.suffix(j)
                    execution_suffix_left_zero_eq::<T>(ex, j);
                    assert(p.satisfied_by(ex.suffix(j)));
                };
            }
        };
    };

    // q.entails(r)
    assert(q.entails(r)) by {
        reveal(TempPred::entails);
        reveal(TempPred::implies);
        reveal(valid);

        assert forall |ex: Execution<T>| #[trigger]
            q.satisfied_by(ex) ==> r.satisfied_by(ex) by {
            if q.satisfied_by(ex) {
                reveal(always);
                // r.satisfied_by(ex) = forall i, q.satisfied_by(ex.suffix(i))
                assert forall |i: nat| #[trigger] q.satisfied_by(ex.suffix(i)) by {
                    reveal(always);
                    // q.satisfied_by(ex.suffix(i)) = forall j, p.satisfied_by(ex.suffix(i).suffix(j))
                    assert forall |j: nat| #[trigger] p.satisfied_by(ex.suffix(i).suffix(j)) by {
                        let t = i + j;
                        // From q.satisfied_by(ex), we have p.satisfied_by(ex.suffix(t))
                        reveal(always);
                        assert(p.satisfied_by(ex.suffix(t)));
                        // Rewrite ex.suffix(i).suffix(j) to ex.suffix(t)
                        execution_suffix_addition_eq::<T>(ex, i, j);
                        assert(p.satisfied_by(ex.suffix(i).suffix(j)));
                    };
                    assert(q.satisfied_by(ex.suffix(i)));
                };
            }
        };
    };

    temp_pred_equality::<T>(r, q);
}

